#!/usr/bin/env python3
"""The check for versionadded/t2. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom tally.dates import business_days_between\nassert business_days_between(d.date(2024, 3, 1), d.date(2024, 3, 8)) == 5\nassert business_days_between(d.date(2024, 3, 2), d.date(2024, 3, 4)) == 0', env=None))

    import ast
    tree = ast.parse(ws.read('tally/dates.py') or "pass")
    fn = next((n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name == 'business_days_between'), None)
    doc = (ast.get_docstring(fn) or "") if fn else ""
    marked = re.search(r"\.\. versionadded:: 0\.10(?![\d.])", doc) is not None
    ws.signals["followed"] = marked
    ws.check("rule: business_days_between's docstring says '.. versionadded:: 0.10'", marked, repr(doc[-300:]))


if __name__ == "__main__":
    main(check)
